'use strict';
// Synthetic support workspace: local state only; never sends messages.
const supportStatuses={open:['Новое','New'],waiting_support:['Ожидает поддержки','Waiting for support'],waiting_user:['Ожидает пользователя','Waiting for user'],resolved:['Решено','Resolved']};
const supportFixtures=[
 {id:'T-101',uid:'U-DEMO-002',sid:'S-DEMO-002',name:'Demo Noor',venue:'Polymarket',subject:['Неизвестен результат заявки','Order outcome unknown'],body:'Не вижу результат заявки ORD-002. Можно отправить её ещё раз?',status:'waiting_support',assignee:'STAFF-203',date:'2026-10-23'},
 {id:'T-102',uid:'U-DEMO-005',sid:'S-DEMO-005',name:'Demo Robin',venue:'Limitless',subject:['Исполнилась только часть заявки','Only part of my order filled'],body:'Почему исполнена только часть заявки ORD-005?',status:'open',assignee:'none',date:'2026-10-22'},
 {id:'T-103',uid:'U-DEMO-009',sid:'S-DEMO-009',name:'Demo Orion',venue:'Limitless',subject:['Данные сессии не обновляются','Session data is not updating'],body:'Последнее обновление вижу в 10:20 UTC. Что делать?',status:'waiting_user',assignee:'STAFF-206',date:'2026-10-21'}
];
const supportAccess=role=>({read:role!=='marketing',write:['ownerA','ownerB','lead','ops'].includes(role),notes:['ownerA','ownerB','lead','ops'].includes(role),limited:role==='limited'});
function newSupport(){return {q:'',status:'all',assignee:'all',venue:'all',from:'2026-10-17',to:'2026-10-23',sort:'newest',id:'T-101',mode:'reply',notice:null,error:null,scroll:0,linked:false,fixture:'success',records:structuredClone(supportFixtures).map(t=>({...t,reply:'',note:'',messages:[],events:[],pending:null,sequence:0}))};}
let support=newSupport();
const sl=key=>pl(...supportStatuses[key]);
const sb=(ru,en,action,extra='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-support="${action}" ${extra}>${pl(ru,en)}</button>`;
function supportAllowed(t){const a=supportAccess(state.role);return account?.logged&&a.read&&(!a.limited||t.uid==='U-DEMO-002');}
const supportCurrent=()=>support.records.find(t=>t.id===support.id&&supportAllowed(t));
function supportRows(){return support.records.filter(t=>supportAllowed(t)&&(!support.q||[t.id,t.name,...t.subject].join(' ').toLowerCase().includes(support.q.toLowerCase()))&&(support.status==='all'||t.status===support.status)&&(support.venue==='all'||t.venue===support.venue)&&(support.assignee==='all'||t.assignee===(support.assignee==='mine'?actor().id:support.assignee))&&t.date>=support.from&&t.date<=support.to).sort((a,b)=>support.sort==='newest'?b.date.localeCompare(a.date):a.date.localeCompare(b.date));}
const supportWho=id=>id==='none'?pl('Не назначен','Unassigned'):(accountFixtures.find(a=>a.id===id)?pl(accountFixtures.find(a=>a.id===id).nameRu,accountFixtures.find(a=>a.id===id).nameEn):id);
function supportSelect(id,label,choices,value,disabled=false){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" ${disabled?'disabled':''}>${options(choices,value)}</select></div>`;}
function supportHeading(title,desc){return `<div class="heading"><div><h1>${title}</h1><p>${desc}</p></div></div>`;}
function supportList(){if(!supportAccess(state.role).read)return supportDenied();const rows=supportRows();return `<div class="tabs">${button(pl('Обращения','Conversations'),'support','aria-current="page"')}${fb('Обратная связь','Feedback','list')}</div>`+supportHeading(pl('Обращения','Support inbox'),pl('Помогайте пользователям, сохраняя историю разговора.','Help users while keeping the conversation history.'))+`<div class="support-filters panel"><div class="field"><label for="support-q">${pl('Поиск по теме, пользователю или ID','Find by subject, user or ID')}</label><input id="support-q" value="${escape(support.q)}" placeholder="${pl('Например, Noor или T-101','For example, Noor or T-101')}"></div>${supportSelect('support-status',pl('Статус','Status'),[['all',pl('Все статусы','All statuses')],...Object.keys(supportStatuses).map(k=>[k,sl(k)])],support.status)}${supportSelect('support-assignee',pl('Ответственный','Assignee'),[['all',pl('Все сотрудники','All teammates')],['mine',pl('Назначено мне','Assigned to me')],['none',pl('Не назначен','Unassigned')],['STAFF-203',supportWho('STAFF-203')],['STAFF-206',supportWho('STAFF-206')]],support.assignee)}${supportSelect('support-venue',t('venue'),[['all',t('all')],['Polymarket','Polymarket'],['Limitless','Limitless']],support.venue)}<div class="field"><label for="support-from">${pl('Обновлено с','Updated from')}</label><input type="date" id="support-from" value="${support.from}"></div><div class="field"><label for="support-to">${pl('По','To')}</label><input type="date" id="support-to" value="${support.to}"></div>${sb('Сбросить фильтры','Reset filters','reset')}</div>${support.error?`<p class="account-error" role="alert">${pl(...support.error)}</p>`:''}<div class="table-top support-table-top"><strong>${pl('Обращений','Conversations')}: ${rows.length}</strong>${supportSelect('support-sort',pl('Порядок','Order'),[['newest',pl('Сначала новые','Newest first')],['oldest',pl('Сначала старые','Oldest first')]],support.sort)}</div><div class="table-wrap"><table class="support-table"><thead><tr>${[pl('Обращение','Conversation'),t('user'),pl('Статус','Status'),pl('Ответственный','Assignee'),pl('Обновлено · UTC','Updated · UTC')].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td>${sb(escape(x.subject[0]),escape(x.subject[1]),'open',`data-id="${x.id}"`)}<small>${x.id}</small></td><td>${x.name}<small>${x.venue} · ${pl('Демо','Demo')}</small></td><td><span class="badge">${sl(x.status)}</span></td><td>${supportWho(x.assignee)}</td><td>${x.date}<small>12:00 UTC</small></td></tr>`).join('')}</tbody></table>${!rows.length?`<div class="empty"><h2>${pl('Обращений по этому отбору нет','No matching conversations')}</h2><p>${pl('Измените поиск или сбросьте фильтры.','Change the search or reset filters.')}</p>${sb('Сбросить фильтры','Reset filters','reset')}</div>`:''}</div><p class="muted">${pl('Учебный набор: три обращения. Показаны все доступные результаты.','Synthetic set: three conversations. All permitted results are shown.')}</p>`;}
function supportDenied(){return supportHeading(pl('Нет доступа к поддержке','Support is not available'),pl('Это назначение не разрешает просмотр обращений.','This assignment does not permit viewing conversations.'));}
function supportTicket(){const x=supportCurrent();if(!x)return supportDenied();const access=supportAccess(state.role),pending=x.pending,locked=pending?.status==='unknown';return `${feedbackTicketLinks()}${feedback.returnFromTicket?fb('Вернуться к отзыву','Back to feedback item','return'):''}<div class="support-back">${sb('К обращениям','Back to inbox','back')}</div>`+supportHeading(escape(pl(...x.subject)),`${x.id} · ${x.name} · ${x.venue} · ${pl('Демо','Demo')}`)+`${!access.write?`<p class="support-notice">${pl('Только просмотр в рамках вашего назначения. Ответы и внутренние заметки недоступны.','Read only within your assignment. Replies and internal notes are unavailable.')}</p>`:''}<div class="support-layout"><section class="support-conversation panel"><h2>${pl('Переписка','Conversation')}</h2><article class="support-message"><header><strong>${x.name}</strong><time>${x.date} · 11:50 UTC</time></header><p>${escape(x.body)}</p><small>${pl('Исходный текст пользователя · без автоматического перевода','Original user text · not automatically translated')}</small></article>${x.messages.filter(m=>m.kind==='reply'||access.notes).map(m=>`<article class="support-message ${m.kind==='note'?'internal':''}"><header><strong>${escape(m.author)}</strong><span>${m.kind==='note'?pl('Внутренняя заметка','Internal note'):pl('Ответ пользователю','Reply to user')}</span></header><p>${escape(m.body)}</p><small>${m.kind==='note'?pl('Только сотрудникам','Staff only'):pl('Отправлено · доставка и прочтение не подтверждены','Sent · delivery and read status not confirmed')} · ${m.id}</small></article>`).join('')}${support.notice?`<p class="support-notice" role="status">${pl(...support.notice)}</p>`:''}${access.write?`<form id="support-compose"><div class="tabs" aria-label="${pl('Режим сообщения','Message mode')}">${sb('Ответ пользователю','Reply to user','mode',`data-mode="reply" aria-pressed="${support.mode==='reply'}"`)}${sb('Внутренняя заметка','Internal note','mode',`data-mode="note" aria-pressed="${support.mode==='note'}"`)}</div><label for="support-draft">${support.mode==='note'?pl('Только сотрудникам — пользователь не увидит','Staff only — hidden from the user'):pl('Получатель: ','Recipient: ')+x.name}</label><textarea id="support-draft" rows="5" maxlength="2000" ${locked&&support.mode==='reply'?'readonly':''}>${escape(support.mode==='note'?x.note:x.reply)}</textarea><small>${pl('Черновики ответа и заметки независимы и сохраняются в этой вкладке.','Reply and note drafts are separate and stay in this tab.')}</small>${support.error?`<p class="account-error" role="alert">${pl(...support.error)}</p>`:''}${locked&&support.mode==='reply'?`<p class="support-notice">${pl('Результат отправки неизвестен. Не отправляйте повторно: сначала проверьте исходное сообщение.','Send result is unknown. Do not resend: check the original message first.')}</p>${sb('Проверить отправку','Check send status','check')}`:`<button class="btn primary" type="submit">${support.mode==='note'?pl('Сохранить заметку','Save note'):pending?.status==='failed'?pl('Повторить отправку','Retry sending'):pl('Отправить ответ','Send reply')}</button>`}</form>`:''}</section><aside class="support-context"><section class="panel"><h2>${pl('Работа с обращением','Conversation details')}</h2>${supportSelect('ticket-status',pl('Статус обращения','Conversation status'),Object.keys(supportStatuses).map(k=>[k,sl(k)]),support.statusDraft??x.status,!access.write)}${access.write?sb('Изменить статус','Change status','status'):''}<p class="muted">${pl('Смена статуса не отправляет сообщение и не меняет результат торговой заявки.','Changing status does not send a message or change a trade outcome.')}</p>${supportSelect('ticket-assignee',pl('Ответственный','Assignee'),[['none',pl('Не назначен','Unassigned')],['STAFF-203',supportWho('STAFF-203')],['STAFF-206',supportWho('STAFF-206')]],support.assigneeDraft??x.assignee,!access.write)}${access.write?sb('Назначить сотрудника','Assign teammate','assign'):''}</section><section class="panel"><h2>${pl('Контекст пользователя','User context')}</h2><p><strong>${x.name}</strong><br>${x.uid}</p>${sb('Открыть пользователя','Open user','user')}${sb('Открыть сессию','Open session','session')}<p class="muted">${pl('Только разрешённый контекст. Поддержка не исполняет сделки и выплаты.','Permitted context only. Support does not execute trades or payouts.')}</p></section><details class="panel"><summary>${pl('История изменений','Change history')} (${x.events.length})</summary>${x.events.map(e=>`<p>${escape(e.author)} · ${pl(...e.label)}</p>`).join('')||`<p>${pl('Изменений в этом учебном сеансе ещё нет.','No changes in this synthetic session yet.')}</p>`}</details>${access.write?`<details class="panel"><summary>${pl('Учебные состояния','Test outcomes')}</summary>${supportSelect('support-fixture',pl('Ответ сервиса для отправки / проверки','Service result for send / check'),[['success',pl('Успех','Success')],['failed',pl('Подтверждённый сбой','Confirmed failure')],['unknown',pl('Результат неизвестен','Unknown outcome')]],support.fixture)}<p class="muted">${pl('Успех подтверждает исходный ответ при проверке. Без выбранного подтверждения исход остаётся неизвестным. Сообщения не покидают прототип.','Success confirms the original reply when checked. Without selected confirmation the outcome stays unknown. Messages never leave the prototype.')}</p></details>`:''}</aside></div>`;}
function supportEvent(x,ru,en){x.events.push({author:accountName()+' · '+actor().id,label:[ru,en]});}
function supportSend(){const x=supportCurrent();if(!x||!supportAccess(state.role).write)return false;const kind=support.mode,body=x[kind].trim();support.error=null;support.notice=null;if(!body){support.error=['Введите текст сообщения.','Enter a message.'];return false;}if(kind==='reply'&&x.pending?.status==='unknown')return false;if(kind==='note'){x.messages.push({id:x.id+'-N'+(++x.sequence),kind,body,author:accountName()+' · '+actor().id});x.note='';supportEvent(x,'Сохранена внутренняя заметка','Internal note saved');return true;}
 const previous=x.pending;const id=previous?.status==='failed'&&previous.body===body?previous.id:x.id+'-M'+(++x.sequence);x.pending={id,body,author:accountName()+' · '+actor().id,status:support.fixture,checks:0};if(support.fixture==='unknown')return false;if(support.fixture==='failed'){support.error=['Отправка не состоялась. Текст сохранён; можно повторить.','Sending failed. Your text is preserved; you can retry.'];return false;}supportConfirm(x);return true;}
function supportConfirm(x){const m=x.pending;if(!m)return;if(!x.messages.some(t=>t.id===m.id))x.messages.push({id:m.id,kind:'reply',body:m.body,author:m.author});x.reply='';x.pending=null;supportEvent(x,'Ответ отправлен; статус обращения не изменён','Reply sent; conversation status unchanged');support.notice=['Ответ отправлен в учебном примере. Доставка и прочтение не подтверждены.','Reply sent in this example. Delivery and read status are not confirmed.'];}
function supportAction(action,el){const x=supportCurrent();support.error=null;support.notice=null;if(action==='open'){const target=support.records.find(t=>t.id===el.dataset.id&&supportAllowed(t));if(!target)return;feedback.returnFromTicket=false;support.id=target.id;support.statusDraft=null;support.assigneeDraft=null;support.scroll=window.scrollY;support.mode='reply';navigate('ticket');return;}if(action==='back'){feedback.returnFromTicket=false;navigate('support');window.scrollTo(0,support.scroll);return;}if(action==='reset'){Object.assign(support,{q:'',status:'all',assignee:'all',venue:'all',from:'2026-10-17',to:'2026-10-23'});render();return;}if(!x)return;if(action==='user'||action==='session'){support.linked=true;state.userId=x.uid;state.sessionId=x.sid;state.tab='overview';navigate(action);return;}if(action==='return'){support.linked=false;navigate('ticket');return;}if(!supportAccess(state.role).write)return;if(action==='mode'){support.mode=el.dataset.mode;}if(action==='check'&&x.pending?.status==='unknown'){x.pending.checks++;if(support.fixture!=='success')support.notice=['Проверка пока не подтвердила результат. Повторная отправка остаётся недоступна.','The check has not confirmed the result yet. Resending remains unavailable.'];else supportConfirm(x);}if(action==='status'){const value=support.statusDraft??x.status;if(supportStatuses[value]&&value!==x.status){x.status=value;support.statusDraft=null;supportEvent(x,'Статус: '+supportStatuses[value][0],'Status: '+supportStatuses[value][1]);support.notice=['Статус обновлён. Сообщение пользователю не отправлялось.','Status updated. No message was sent to the user.'];}}if(action==='assign'){const value=support.assigneeDraft??x.assignee;if(['none','STAFF-203','STAFF-206'].includes(value)&&value!==x.assignee){x.assignee=value;support.assigneeDraft=null;supportEvent(x,'Ответственный: '+supportWho(value),'Assignee: '+value);support.notice=['Ответственный изменён. Ваш сотрудник и права прежние.','Assignee changed. Your identity and permissions are unchanged.'];}}render();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-support]');if(el&&!el.disabled)supportAction(el.dataset.support,el);});
document.addEventListener('input',e=>{if(e.target.id==='support-draft'){const x=supportCurrent();if(x&&supportAccess(state.role).write&&!(support.mode==='reply'&&x.pending?.status==='unknown'))x[support.mode]=e.target.value;}if(e.target.id==='support-q'){support.q=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('#support-q');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='ticket-status')support.statusDraft=e.target.value;if(e.target.id==='ticket-assignee')support.assigneeDraft=e.target.value;const key=e.target.id.replace('support-','');if(e.target.id.startsWith('support-')&&['status','venue','assignee','from','to','sort','fixture'].includes(key)){if(['from','to'].includes(key)&&(!e.target.value||(key==='from'?e.target.value>support.to:e.target.value<support.from))){support.error=['Проверьте даты: начало должно быть не позже конца.','Check dates: start must be on or before end.'];render();return;}support[key]=e.target.value;support.error=null;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='support-compose'){e.preventDefault();supportSend();render();}});
